const enc=new TextEncoder();
async function mac(secret,msg){const k=await crypto.subtle.importKey("raw",enc.encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return Array.from(new Uint8Array(await crypto.subtle.sign("HMAC",k,enc.encode(msg)))).map(x=>x.toString(16).padStart(2,"0")).join("")}
async function role(r,e){const t=(r.headers.get("cookie")||"").match(/(?:^|;\s*)pp_session=([^;]+)/)?.[1];if(!t||!e.SESSION_SECRET)return null;const [expiry,userRole,sig]=t.split('.');if(!/^\d+$/.test(expiry)||Number(expiry)<Date.now()||!['manager','kitchen','counter'].includes(userRole))return null;return sig===await mac(e.SESSION_SECRET,expiry+'.'+userRole)?userRole:null}
